{
  "story": "For “The cat sat on the …”, inspect scores for three word-sized tokens: mat, rug, moon. Advance to probabilities, then the highest-probability guess. This toy uses only these tokens, fixed scores, temperature one, and greedy decoding.",
  "aha": {
    "stateId": "guess",
    "observation": "Softmax converts scores into probabilities; greedy decoding chooses the most probable token, not a certain answer."
  },
  "layout": {
    "preset": "stepper-states.algorithm-collection",
    "width": 640
  },
  "parts": [
    {
      "id": "steps",
      "kind": "step-rail",
      "presentation": "Place below the story and instructions. Show the active step and completed trace here only.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "candidate-picture",
      "kind": "fixed-picture",
      "presentation": "Show one candidate row with fixed token positions. Region phases follow variant.states order. Highlight the active region without animation.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "candidate-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the candidate row without covering it. Identify the mechanism without repeating numerical values.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "measurements",
      "kind": "value-readout",
      "presentation": "Keep token readouts in picture order. Scores are unitless; probabilities cover the same toy vocabulary and round to one decimal percent.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Process step",
      "presentation": "Previous and Next; default Scores; increment one state. Keep boundary names when disabled. Every state persists until action. Provide keyboard operation and visible focus."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore Scores and all defaults. Parameter-control budget: zero, excluding navigation and reset. Support Enter and Space with visible focus."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Three-token softmax with greedy decoding",
        "regions": [
          {
            "id": "candidates",
            "label": "Next-token candidates",
            "phases": [
              "Scores: mat leads; rug follows; moon trails.",
              "Probabilities: mat has the largest share; rug and moon remain possible.",
              "Guess: mat selected; rug and moon unselected."
            ]
          }
        ],
        "links": [],
        "states": [
          {
            "id": "scores",
            "label": "Scores",
            "short": "Compare",
            "sentence": "The candidate row starts with the transformer's scores.",
            "why": "Scores rank candidates, but they are not probabilities.",
            "active": [
              "candidates"
            ],
            "calloutRegion": "candidates",
            "readouts": [
              {
                "id": "mat",
                "label": "mat — score",
                "value": "2"
              },
              {
                "id": "rug",
                "label": "rug — score",
                "value": "1"
              },
              {
                "id": "moon",
                "label": "moon — score",
                "value": "0"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Scores ready; no token selected."
              }
            ]
          },
          {
            "id": "probabilities",
            "label": "Probabilities",
            "short": "Normalize",
            "sentence": "Softmax turns the candidate scores into probability shares.",
            "why": "Exponentiate each score, then divide by their sum; the largest score keeps the largest share.",
            "active": [
              "candidates"
            ],
            "calloutRegion": "candidates",
            "readouts": [
              {
                "id": "mat",
                "label": "mat — probability",
                "value": "66.5%"
              },
              {
                "id": "rug",
                "label": "rug — probability",
                "value": "24.5%"
              },
              {
                "id": "moon",
                "label": "moon — probability",
                "value": "9.0%"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Probabilities normalized; no token selected."
              }
            ]
          },
          {
            "id": "guess",
            "label": "Guess",
            "short": "Choose",
            "sentence": "The candidate row marks mat as the greedy next-token guess.",
            "why": "Greedy decoding chooses the largest probability; the remaining probability shows why that choice is not certain.",
            "active": [
              "candidates"
            ],
            "calloutRegion": "candidates",
            "readouts": [
              {
                "id": "mat",
                "label": "mat — probability",
                "value": "66.5%"
              },
              {
                "id": "rug",
                "label": "rug — probability",
                "value": "24.5%"
              },
              {
                "id": "moon",
                "label": "moon — probability",
                "value": "9.0%"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Guess selected; alternatives remain possible."
              }
            ]
          }
        ]
      }
    ]
  }
}
